import {simulate,defaults,HBAR} from './engine.js';
const $=id=>document.getElementById(id);let run=simulate(),cursor=0,playing=true,orbit=true,angle=.7,tilt=.28,zoom=1,selected=0,pol='x',dirty=false,last=0,screenSites=[];
const canvases=['scene','matrix','clocks','spectrum','trace'];
function surface(id){let c=$(id),r=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(r.width*dpr)||c.height!==Math.round(r.height*dpr)){c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);}let x=c.getContext('2d');x.setTransform(dpr,0,0,dpr,0,0);x.clearRect(0,0,r.width,r.height);return [x,r.width,r.height];}
function line(ctx,pts,color,width=1){ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
function sphere(ctx,x,y,r,energy=0,alpha=1){let grad=ctx.createRadialGradient(x-r*.35,y-r*.4,0,x,y,r);grad.addColorStop(0,energy>.05?'#fff1ca':'#aac5b8');grad.addColorStop(.3,energy>.05?`rgb(239,${Math.round(155+energy*45)},109)`:'#466d5c');grad.addColorStop(1,energy>.05?'#754b2d':'#132d24');ctx.globalAlpha=alpha;ctx.fillStyle=grad;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}
function molecular(f){let [c,w,h]=surface('scene');const scale=Math.min(w/9,h/7)*zoom,proj=r=>{let [x,y,z]=r;let xx=x*Math.cos(angle)-y*Math.sin(angle),yy=x*Math.sin(angle)+y*Math.cos(angle);return [w*.48+xx*scale,h*.53-(z*Math.cos(tilt)-yy*Math.sin(tilt))*scale,yy*Math.cos(tilt)+z*Math.sin(tilt)];};
// Quiet laboratory ground grid.
for(let k=-4;k<=4;k++){line(c,[proj([k,-4,-2.7]),proj([k,4,-2.7])],'#27443a55');line(c,[proj([-4,k,-2.7]),proj([4,k,-2.7])],'#27443a55');}
// Optical envelope: sampled classical drive, displayed as a schematic wave ribbon.
let pulse=f.pulse;let wave=[];for(let j=0;j<=120;j++){let x=-4+j/15;wave.push(proj([x,0,Math.sin(x*4-f.t*.08)*.22*pulse]));}line(c,wave,`rgba(145,223,200,${.08+.5*pulse})`,1.6);if(pulse>.02){c.save();let x=w*(.05+.9*Math.min(1,Math.max(0,(f.t-5)/150)));let grad=c.createLinearGradient(x-40,0,x+40,0);grad.addColorStop(0,'#91dfc800');grad.addColorStop(.5,`rgba(145,223,200,${pulse*.11})`);grad.addColorStop(1,'#91dfc800');c.fillStyle=grad;c.fillRect(x-40,80,80,h-110);c.restore();}
const g=run.m.g;let path=[];for(let a=0;a<=(g.length-1)*20;a++){let i=a/20,th=i*run.m.p.twist*Math.PI/180;path.push(proj([run.m.p.radius*Math.cos(th),run.m.p.radius*Math.sin(th),(i-(g.length-1)/2)*run.m.p.rise]));}line(c,path,'#789b7555',7);line(c,path,'#9ec49b88',1.2);
screenSites=g.map((s,i)=>({i,q:proj(s.r)}));
// Coupling links and calculated excitation currents. No decorative random motion.
for(let i=0;i<g.length;i++)for(let j=i+1;j<g.length;j++){let coupling=run.m.H[(i+1)*run.m.d+j+1];if(Math.abs(coupling)<.002)continue;let a=screenSites[i].q,b=screenSites[j].q;let current=2*coupling*f.rho[run.m.d**2+(i+1)*run.m.d+j+1]/HBAR;line(c,[a,b],`rgba(116,167,145,${Math.min(.32,Math.abs(coupling)*7)})`,.7);if(Math.abs(current)>1e-5){let u=((f.t*.012*(current>0?1:-1)+i*.173)%1+1)%1;c.beginPath();c.arc(a[0]+u*(b[0]-a[0]),a[1]+u*(b[1]-a[1]),1.5,0,7);c.fillStyle='#d0ffe9';c.fill();}}
for(let {i,q} of [...screenSites].sort((a,b)=>a.q[2]-b.q[2])){let s=g[i],e=Math.min(1,f.pop[i]*14),rad=7+q[2]*.45;let ring=[];for(let k=0;k<=6;k++){let th=k*Math.PI/3;ring.push(proj(s.r.map((v,a)=>v+(.28*Math.cos(th)*s.mu[a]+.18*Math.sin(th)*(a===2?1:0)))));}line(c,ring,e>.05?'#e2ac74aa':'#6b918088',1.4);for(let k=0;k<6;k++)sphere(c,ring[k][0],ring[k][1],2.5,e,.8);if(e>.01){let glow=c.createRadialGradient(q[0],q[1],1,q[0],q[1],rad*4);glow.addColorStop(0,`rgba(245,167,104,${e*.5})`);glow.addColorStop(1,'#efa76f00');c.fillStyle=glow;c.fillRect(q[0]-rad*4,q[1]-rad*4,rad*8,rad*8);}sphere(c,q[0],q[1],rad,e);let tip=proj(s.r.map((v,k)=>v+.55*s.mu[k]));line(c,[q,tip],'#9cdfcbaa',1.2);let a=Math.atan2(tip[1]-q[1],tip[0]-q[0]);line(c,[[tip[0]-5*Math.cos(a-.5),tip[1]-5*Math.sin(a-.5)],tip,[tip[0]-5*Math.cos(a+.5),tip[1]-5*Math.sin(a+.5)]],'#9cdfcbaa',1);if(i===selected){c.beginPath();c.arc(q[0],q[1],rad+6,0,7);c.strokeStyle='#d5e4bc';c.lineWidth=1;c.stroke();}c.fillStyle='#adc4b6';c.font='9px monospace';c.fillText(String(i+1).padStart(2,'0'),q[0]+rad+7,q[1]+3);}
$('siteName').textContent=String(selected+1).padStart(2,'0');$('sitePop').textContent='Population '+f.pop[selected].toFixed(4);$('sitePhase').textContent=f.amp[selected]>1e-6?'Phase '+f.phase[selected].toFixed(2)+' rad':'Phase undefined';$('pulseState').textContent=f.t<30?'PULSE APPROACHING':f.t<140?'OPTICAL EXCITATION':'FREE EVOLUTION & RELAXATION';}
function matrix(f){let [c,w,h]=surface('matrix'),n=run.m.p.n,s=Math.min(w-35,h-28)/n,x=(w-s*n)/2,y=12,max=Math.max(...f.pop,.001);for(let i=0;i<n;i++)for(let j=0;j<n;j++){let k=(i+1)*run.m.d+j+1,v=Math.hypot(f.rho[k],f.rho[run.m.d**2+k]),a=Math.min(1,v/max);c.fillStyle=`rgb(${Math.round(20+215*a)},${Math.round(43+123*a)},${Math.round(35+74*a)})`;c.fillRect(x+j*s+1,y+i*s+1,s-2,s-2);}c.strokeStyle='#b6e0bd';c.lineWidth=1;c.strokeRect(x+selected*s,y+selected*s,s,s);$('matrixMax').textContent='0–'+max.toFixed(3);}
function clocks(f){let [c,w,h]=surface('clocks'),cx=w/2,cy=h/2,outer=Math.min(w,h)*.39,max=Math.max(...f.amp,.001);c.strokeStyle='#355044';c.setLineDash([3,5]);c.beginPath();c.arc(cx,cy,outer,0,7);c.stroke();c.setLineDash([]);for(let i=0;i<run.m.p.n;i++){let a=i*2*Math.PI/run.m.p.n-Math.PI/2,x=cx+outer*Math.cos(a),y=cy+outer*Math.sin(a),r=5+f.amp[i]/max*14;line(c,[[cx,cy],[x,y]],'#2f4b3f',.6);c.strokeStyle=i===selected?'#efa76f':'#6fb89c';c.beginPath();c.arc(x,y,r,0,7);c.stroke();if(f.amp[i]>1e-6)line(c,[[x,y],[x+r*Math.cos(f.phase[i]),y-r*Math.sin(f.phase[i])]],'#c3ebd5',1.3);c.fillStyle='#729c86';c.font='8px monospace';c.fillText(i+1,x-3,y+r+10);}c.fillStyle='#b6e3cd';c.font='24px Georgia';c.textAlign='center';c.fillText(f.order.toFixed(2),cx,cy+4);c.font='8px system-ui';c.fillStyle='#789e8a';c.fillText('PHASE ALIGNMENT',cx,cy+22);c.textAlign='left';$('phaseOrder').textContent='R = '+f.order.toFixed(3);}
function spectrum(){let [c,w,h]=surface('spectrum'),pts=run.spectrum.points,max=Math.max(...pts.map(p=>p.y),.001),left=28,right=w-10,top=22,bottom=h-28,X=x=>left+(x-4.8)/.4*(right-left),Y=y=>bottom-y/max*(bottom-top);for(let v=0;v<=1;v+=.25)line(c,[[left,Y(v*max)],[right,Y(v*max)]],'#263c32',.6);let path=pts.map(p=>[X(p.x),Y(p.y)]);let fill=c.createLinearGradient(0,top,0,bottom);fill.addColorStop(0,'#8bcaa755');fill.addColorStop(1,'#8bcaa700');c.beginPath();c.moveTo(left,bottom);path.forEach(p=>c.lineTo(...p));c.lineTo(right,bottom);c.closePath();c.fillStyle=fill;c.fill();line(c,path,'#9ad9b5',1.7);c.setLineDash([3,4]);line(c,[[X(5),top],[X(5),bottom]],'#eab079',1);c.setLineDash([]);c.font='9px monospace';c.fillStyle='#87a492';for(let x=4.8;x<5.21;x+=.1)c.fillText(x.toFixed(1),X(x)-9,bottom+18);c.fillText('relative strength',left,12);}
function trace(f){let [c,w,h]=surface('trace'),left=35,right=w-10,top=18,bottom=h-22,fs=run.frames,max=Math.max(1,...fs.map(f=>f.coherence)),X=t=>left+t/500*(right-left),Y=v=>bottom-v/max*(bottom-top);c.font='9px monospace';c.fillStyle='#79998a';for(let i=0;i<=4;i++){let y=max*i/4;line(c,[[left,Y(y)],[right,Y(y)]],'#2b4035',.5);c.fillText(y.toFixed(2),0,Y(y)+3);}for(let t=0;t<=500;t+=100)c.fillText(t+'',X(t)-5,h-4);for(let [key,color] of [['pulse','#758d97'],['excited','#efa76f'],['coherence','#80ddc9']]){if(key==='pulse')c.setLineDash([3,4]);line(c,fs.map(f=>[X(f.t),Y(f[key])]),color,1.5);c.setLineDash([]);}line(c,[[X(f.t),top],[X(f.t),bottom]],'#d8e7d1aa',1);}
function draw(){let f=run.frames[Math.min(run.frames.length-1,Math.floor(cursor))];molecular(f);matrix(f);clocks(f);spectrum();trace(f);$('time').textContent=f.t.toFixed(0)+' fs';$('scrub').value=Math.floor(cursor);$('excited').textContent=f.excited.toFixed(3);$('pr').innerHTML=f.pr.toFixed(2)+' <em>sites</em>';$('coherence').textContent=f.coherence.toFixed(3);}
function frame(now){let delta=last?Math.min(.1,(now-last)/1000):0;last=now;if(playing){cursor+=delta*Number($('speed').value);if(cursor>=run.frames.length-1){cursor=run.frames.length-1;playing=false;$('play').textContent='▶';$('play').setAttribute('aria-label','Play trajectory');}}if(orbit)angle+=delta*.09;draw();requestAnimationFrame(frame);}requestAnimationFrame(frame);
$('play').onclick=()=>{if(cursor>=run.frames.length-1)cursor=0;playing=!playing;$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'Pause playback':'Play trajectory');};$('replay').onclick=()=>{cursor=0;playing=true;$('play').textContent='Ⅱ';};$('scrub').oninput=()=>{cursor=+$('scrub').value;playing=false;$('play').textContent='▶';};$('rotate').onclick=()=>{orbit=!orbit;$('rotate').setAttribute('aria-pressed',orbit);$('rotate').style.color=orbit?'#91dfc8':'#78998a';};
let drag=null; $('scene').onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};$('scene').setPointerCapture(e.pointerId);};$('scene').onpointermove=e=>{if(!drag)return;angle+=(e.clientX-drag.x)*.008;tilt=Math.max(-1,Math.min(1,tilt+(e.clientY-drag.y)*.005));drag.x=e.clientX;drag.y=e.clientY;};$('scene').onpointerup=e=>{if(drag&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<5){let r=$('scene').getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let closest=[...screenSites].sort((a,b)=>Math.hypot(a.q[0]-x,a.q[1]-y)-Math.hypot(b.q[0]-x,b.q[1]-y))[0];if(closest&&Math.hypot(closest.q[0]-x,closest.q[1]-y)<35)selected=closest.i;}drag=null;};$('scene').addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.6,Math.min(1.6,zoom-e.deltaY*.001));},{passive:false});
function updateLabels(){for(let id of ['twist','j','drive','gamma','fluct'])$(id+'Value').textContent=id==='twist'?$(id).value+'°':id==='gamma'?(+$('gamma').value/1000).toFixed(3)+' fs⁻¹':$(id).value+' meV';}
function changed(){dirty=true;updateLabels();$('runStatus').textContent='Settings changed · run to apply';}
for(let id of ['twist','j','drive','gamma','fluct'])$(id).oninput=changed;
function setPol(p){pol=p;document.querySelectorAll('[data-pol]').forEach(b=>{b.classList.toggle('active',b.dataset.pol===pol);b.setAttribute('aria-pressed',b.dataset.pol===pol);});}
document.querySelectorAll('[data-pol]').forEach(b=>b.onclick=()=>{setPol(b.dataset.pol);changed();});
function execute(){let params={twist:+$('twist').value,j:+$('j').value/1000,drive:+$('drive').value/1000,gamma:+$('gamma').value/1000,fluct:+$('fluct').value/1000,pol};$('run').disabled=true;$('runStatus').textContent='Integrating the density matrix…';setTimeout(()=>{run=simulate(params);cursor=0;playing=true;dirty=false;$('play').textContent='Ⅱ';$('run').disabled=false;$('runStatus').textContent='251 frames · 0.5 fs integration step';},25);}
$('run').onclick=execute;$('preset').onchange=()=>{let p=$('preset').value;$('j').value=p==='isolated'?0:25;$('gamma').value=p==='noise'?15:3;$('fluct').value=p==='dynamic'?15:0;changed();execute();};$('reset').onclick=()=>{for(let [k,v] of Object.entries({twist:55,j:25,drive:6,gamma:3,fluct:0}))$(k).value=v;$('preset').value='default';setPol('x');updateLabels();execute();};
$('download').onclick=()=>{let data={schema:'helix-light-v0.1',scope:'Illustrative one-excitation Lindblad model; PTC-inspired clock representation, not time-crystal certification',parameters:run.m.p,geometry:run.m.g,spectrum:run.spectrum,frames:run.frames};let url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='helix-light-trajectory.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('closeModal').onclick=()=>$('modal').close();$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').close();};
$('modelBtn').onclick=()=>{$('modalBody').innerHTML=`<div class="eyebrow">MODEL / EVIDENCE</div><h2>What you are watching</h2><p>A 12-site helical aggregate with one ground state and a single-excitation manifold. The browser integrates a Lindblad master equation using fourth-order Runge–Kutta, with a 0.5 fs step. Every dynamic view reads the same density matrix.</p><h3>Geometry → Hamiltonian → trajectory</h3><p>Chromophores sit on a helix of radius 1.2 nm and rise 0.36 nm/site. The transition dipoles have tangential and axial components. Couplings follow the point-dipole angular factor and inverse-cube separation, with an adjustable illustrative energy scale. No atomic positions or chemical bonds are being calculated.</p><h3>Light and environment</h3><p>A 5.00 eV carrier is treated in the rotating-wave approximation. The displayed wave is a schematic of the pulse envelope; femtosecond optical cycles are not drawn to scale. Site-local dephasing and decay to the ground state are explicit Lindblad channels. Optional sinusoidal site-energy modulation is a deterministic perturbation, not thermal molecular dynamics.</p><h3>The clock connection</h3><p>Clock radii encode |ρᵢ₀|, and hands encode arg(ρᵢ₀) in the laser rotating frame. These are optical coherences, not electron trajectories. Phase alignment is not an entanglement witness or proof of a PTC. The absorption panel uses the initial static Hamiltonian; it is not a time-resolved spectrum.</p><h3>Scope of version 0.1</h3><p>Parameters are illustrative and have not been calibrated to P1H11. Molecular backaction, explicit electron-density calculations, magnetic/RF coupling, condensation, fluorescence and time-crystal certification are future modules. No arbitrary paper score drives the dynamics.</p><p><a href="specification.html" target="_blank">Full executable specification and roadmap ↗</a></p>`;$('modal').showModal();};
$('validationBtn').onclick=async()=>{let v=await fetch('validation.json').then(r=>r.json());$('modalBody').innerHTML='<div class="eyebrow">NUMERICAL VALIDATION</div><h2>Checked against independent dynamics.</h2><p>'+v.scope+'</p><table><tr><th>Check</th><th>Error</th><th>Tolerance</th></tr>'+v.tests.map(t=>`<tr><td>✓ ${t.name}</td><td>${t.value.toExponential(2)}</td><td>${t.tolerance.toExponential(1)}</td></tr>`).join('')+'</table><p>The independent reference uses SciPy DOP853 at rtol 10⁻¹⁰. These checks establish numerical consistency for the reference preset, not experimental validation of the material.</p>';$('modal').showModal();};
